// _mixins.scss

// Parallax background effect
@mixin parallax-background($image-url, $height: 100vh, $overlay: 0.4) {
  position: relative;
  background-image: url($image-url);
  background-attachment: fixed;
  background-position: center;
  background-repeat: no-repeat;
  background-size: cover;
  min-height: $height;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, $overlay);
    z-index: 1;
  }

  > * {
    position: relative;
    z-index: 2;
  }
}

// Usage
.hero-section {
  @include parallax-background('/images/camping-hero.jpg', 100vh, 0.5);

  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
}

.about-section {
  @include parallax-background('/images/forest-bg.jpg', 60vh, 0.3);
}

// _gallery.scss

.gallery-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1rem;
  padding: 2rem;

  @include media-breakpoint-up(md) {
    grid-template-columns: repeat(3, 1fr);
    gap: 1.5rem;
  }

  @include media-breakpoint-up(lg) {
    grid-template-columns: repeat(4, 1fr);
    gap: 2rem;
  }
}

.gallery-item {
  position: relative;
  overflow: hidden;
  border-radius: $border-radius-lg;
  cursor: pointer;

  img {
    width: 100%;
    height: 250px;
    object-fit: cover;
    transition: transform 0.4s ease;
  }

  &::after {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(
      to top,
      rgba(0,0,0,0.7) 0%,
      transparent 50%
    );
    opacity: 0;
    transition: opacity 0.3s ease;
  }

  &:hover {
    img {
      transform: scale(1.1);
    }

    &::after {
      opacity: 1;
    }
  }
}

