// gulpfile.js
const gulp = require('gulp');
const imagemin = require('gulp-imagemin');
const webp = require('gulp-webp');
const responsive = require('gulp-responsive');

// Optimize images
gulp.task('images', () => {
  return gulp.src('src/images/**/*.{jpg,png,gif}')
    .pipe(imagemin([
      imagemin.mozjpeg({ quality: 80, progressive: true }),
      imagemin.optipng({ optimizationLevel: 5 }),
      imagemin.gifsicle({ interlaced: true })
    ]))
    .pipe(gulp.dest('dist/images'));
});

// Generate WebP versions
gulp.task('webp', () => {
  return gulp.src('src/images/**/*.{jpg,png}')
    .pipe(webp({ quality: 80 }))
    .pipe(gulp.dest('dist/images'));
});

// Generate responsive sizes
gulp.task('responsive', () => {
  return gulp.src('src/images/gallery/*.jpg')
    .pipe(responsive({
      '*.jpg': [
        { width: 400, rename: { suffix: '-sm' } },
        { width: 800, rename: { suffix: '-md' } },
        { width: 1200, rename: { suffix: '-lg' } }
      ]
    }))
    .pipe(gulp.dest('dist/images/gallery'));
});

gulp.task('optimize', gulp.parallel('images', 'webp', 'responsive'));

